int __cdecl w35f_getkey2(void)
{
    unsigned short h, c;
    if (w35f_kcnt == 0)
        return 0;
    EnterCriticalSection((void *)&w35f_kcs);
    h = w35f_khead;
    w35f_kcnt--;
    c = w35f_kbuf[h & 0xffff];
    h++;
    w35f_khead = h & 0xf;
    LeaveCriticalSection((void *)&w35f_kcs);
    return c;
}

